Here's a C++ program that prints a pyramid pattern using a recursive function:

```cpp
#include <iostream>

void printSpaces(int spaces) {
    if (spaces <= 0) {
        return;
    }

    std::cout << " ";
    printSpaces(spaces - 1);
}

void printStars(int stars) {
    if (stars <= 0) {
        return;
    }

    std::cout << "*";
    printStars(stars - 1);
}

void printPyramid(int n, int row, int spaces) {
    if (row > n) {
        return;
    }

    printSpaces(spaces);
    printStars(2 * row - 1);
    std::cout << std::endl;
    printPyramid(n, row + 1, spaces - 1);
}

int main() {
    int n;

    do {
        std::cout << "Enter a number (odd and >= 5): ";
        std::cin >> n;

        if (n % 2 != 1 || n < 5) {
            std::cout << "Invalid input. Please enter a valid number." << std::endl;
        }
    } while (n % 2 != 1 || n < 5);

    int spaces = n / 2;

    printPyramid(n, 1, spaces);

    return 0;
}
```

In this program, the `printSpaces` function is used to print the spaces before the stars in each row. The `printStars` function is used to print the stars in each row. The `printPyramid` function recursively prints each row of the pyramid.

